// Store original unprocessed text
let originalText = editor.value;

// Function to strip gradients and frames to get back to original text
function stripFormatting(text) {
    if (!text) return text;

    // Remove edge gradients (pattern: █▓▒░ at start, ░▒▓█ at end)
    let cleaned = text.replace(/^[█▓▒░]+\s+/, '').replace(/\s+[░▒▓█]+$/, '');

    // Remove frames (single/double line boxes or solid blocks)
    // Match frame patterns: ┌─┐, ╔═╗ at top, └─┘, ╚═╝ at bottom, │ at sides
    const framePatterns = [
        /^[┌╔][─═]+[┐╗]\n/,  // Top border
        /\n[└╚][─═]+[┘╝]$/,  // Bottom border
        /^[│║]/,              // Left border
        /[│║]$/,              // Right border
        /^[█]+\n/,           // Solid block top
        /\n[█]+$/,           // Solid block bottom
        /^[█]+/,              // Solid block left
        /[█]+$/               // Solid block right
    ];

    // Remove frame borders
    cleaned = cleaned.split('\n').map(line => {
        // Remove left/right borders
        line = line.replace(/^[│║█]+/, '').replace(/[│║█]+$/, '');
        return line;
    }).filter(line => {
        // Filter out top/bottom border lines
        return !/^[┌┐└┘╔╗╚╝─═█]+$/.test(line);
    }).join('\n');

    // Remove inner padding spaces
    cleaned = cleaned.replace(/^\s+/, '').replace(/\s+$/, '');

    return cleaned;
}

// Update reflow to use original text
function reflowFixed() {
    const settings = getSettings();
    if (!settings.width || settings.width < 10) return;

    // Get current editor value and try to extract original text
    const currentValue = editor.value;

    // If we have stored original, use it; otherwise try to strip formatting
    const sourceText = originalText || stripFormatting(currentValue) || currentValue;

    // Reflow from source
    const reflowed = reflowText(sourceText, settings);
    editor.value = reflowed;

    // Update stored original to be the source (before formatting)
    originalText = sourceText;
}

// Update originalText when user types/pastes
function updateOriginalText() {
    const current = editor.value;
    // Try to detect if text has formatting
    const hasFormatting = /[█▓▒░┌┐└┘╔╗╚╝│║─═]/.test(current);
    if (!hasFormatting) {
        originalText = current;
    }
}

// Override the reflow function
window.reflow = reflowFixed;
window.autoReflow = function() {
    requestAnimationFrame(() => reflowFixed());
};

// Track original text on input
editor.addEventListener('input', updateOriginalText);
editor.addEventListener('paste', () => {
    setTimeout(() => {
        updateOriginalText();
        autoReflow();
    }, 0);
